<script setup lang="ts">
import{ref,computed,onMounted,onUnmounted}from'vue';import LanguageFlag from './LanguageFlag.vue';import{t,choice,setLanguage,language}from'./i18n';import type{Locale}from'../../../packages/i18n/manual';
const menu=ref<HTMLDetailsElement>();const flagLocale=computed(()=>choice.value!=='auto'?choice.value:language.value.toLowerCase().startsWith('zh')?'zh_CN':languages.find(([code])=>language.value.toLowerCase().split(/[-_]/)[0]===code)?.[0]??'en');
const languages:[Locale,string][]=[['en','English'],['es','Español'],['fr','Français'],['de','Deutsch'],['zh_CN','简体中文'],['ar','العربية'],['ru','Русский'],['pt','Português'],['hi','हिन्दी'],['ur','اردو']];

function outside(event:PointerEvent){if(menu.value?.open&&event.target instanceof Node&&!menu.value.contains(event.target))menu.value.open=false;}
function escape(event:KeyboardEvent){if(event.key==='Escape'&&menu.value?.open){menu.value.open=false;menu.value.querySelector('summary')?.focus();event.preventDefault();event.stopPropagation();}}
onMounted(()=>{document.addEventListener('pointerdown',outside);document.addEventListener('keydown',escape);});
onUnmounted(()=>{document.removeEventListener('pointerdown',outside);document.removeEventListener('keydown',escape);});
async function choose(locale:Locale|'auto'){await setLanguage(locale);if(menu.value)menu.value.open=false;}
</script>
<template><details ref="menu" class="language-picker"><summary :aria-label="t('language')" :title="t('language')"><LanguageFlag :locale="flagLocale" /></summary><div class="language-menu" role="group" :aria-label="t('language')"><button type="button" :aria-pressed="choice === 'auto'" @click="choose('auto')">◎ <span>{{ t('languageAutomatic') }}</span></button><button v-for="[locale,label] in languages" :key="locale" type="button" :aria-pressed="choice === locale" @click="choose(locale)"><LanguageFlag :locale="locale" /><span :lang="locale.replace('_','-')" dir="auto">{{ label }}</span><b v-if="choice === locale">✓</b></button></div></details></template>
<style scoped>
.language-picker{position:relative;z-index:45}.language-picker summary{display:flex;align-items:center;gap:6px;padding:8px;border:1px solid var(--border);border-radius:20px;cursor:pointer;font-size:11px;color:var(--muted);list-style:none}.language-picker summary::-webkit-details-marker{display:none}.language-picker summary>svg:not(.language-flag){width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:1.5}.language-menu{position:absolute;inset-inline-end:0;inset-block-start:calc(100% + 8px);width:224px;max-height:min(440px,calc(100vh - 110px));overflow:auto;border:1px solid var(--border);border-radius:16px;padding:8px;background:var(--surface);box-shadow:0 12px 40px #071b2d26}.language-menu button{display:flex;align-items:center;gap:12px;width:100%;padding:9px 10px;border-radius:8px;text-align:start;font-size:13px;background:none;border:0;color:var(--text)}.language-menu button:hover,.language-menu button[aria-pressed=true]{background:var(--subtle)}.language-menu button>span{flex:1}.language-flag{width:28px;height:20px;border-radius:3px;box-shadow:0 0 0 1px #071b2d18;flex-shrink:0}.language-menu b{color:var(--primary)}
</style>
